"""Gold MRR config loader. etl/config/gold_mrr.json is generated by
etl/config/build_gold_mrr_json.py from docs/mrr_discounts_model.md §6. In the
Glue library zip it is gold_mrr/gold_mrr.json, read with pkgutil."""

from __future__ import annotations

import json
import os
import pkgutil
from functools import lru_cache
from pathlib import Path

_DEFAULT = Path(__file__).resolve().parent.parent / "config" / "gold_mrr.json"


@lru_cache(maxsize=1)
def load() -> dict:
    env = os.environ.get("GOLD_MRR_CONFIG_PATH")
    if env:
        text = Path(env).read_text(encoding="utf-8")
    elif _DEFAULT.exists():
        text = _DEFAULT.read_text(encoding="utf-8")
    else:
        data = pkgutil.get_data("gold_mrr", "gold_mrr.json")
        if data is None:
            raise FileNotFoundError("gold_mrr.json is not packaged with gold_mrr/")
        text = data.decode("utf-8")
    return json.loads(text)
